cat > wrangler.jsonc <<'EOF'
{
  "$schema": "node_modules/wrangler/config-schema.json",
  "name": "langchain-nextjs-template",
  "main": ".open-next/worker.js",
  "compatibility_date": "2026-11-01",
  "compatibility_flags": ["nodejs_compat", "global_fetch_strictly_public"],
  "assets": {
    "directory": ".open-next/assets",
    "binding": "ASSETS"
  },
  "services": [
    // Must match "name" above.
    { "binding": "WORKER_SELF_REFERENCE", "service": "langchain-nextjs-template" }
  ],
  // Non-secret config. Secrets (OPENAI_API_KEY, SERPAPI_API_KEY, SUPABASE_*, ...)
  // go in with `npx wrangler secret put NAME`, or .dev.vars for local preview.
  "vars": {
    // The routes stream responses; make LangSmith tracing (if enabled) finish
    // before the request ends.
    "LANGCHAIN_CALLBACKS_BACKGROUND": "false"
  },
  "observability": {
    "enabled": true
  }
}
EOF
cat > open-next.config.ts <<'EOF'
import { defineCloudflareConfig } from "@opennextjs/cloudflare";
import staticAssetsIncrementalCache from "@opennextjs/cloudflare/overrides/incremental-cache/static-assets-incremental-cache";

// Every page is prerendered at build time and nothing revalidates, so the
// prerendered output can be served straight from the Worker's static assets.
// No R2 bucket or KV namespace is needed. Switch to the R2 cache if you add
// ISR / revalidation later.
export default defineCloudflareConfig({
  incrementalCache: staticAssetsIncrementalCache,
  enableCacheInterception: true,
});
EOF
cat > public/_headers <<'EOF'
/_next/static/*
  Cache-Control: public,max-age=31536000,immutable
EOF
cat > .dev.vars.example <<'EOF'
# Copy to .dev.vars for `yarn preview` (runs the app in the local Workers runtime).
# In production, set each secret with `npx wrangler secret put NAME` instead.
NEXTJS_ENV=development

OPENAI_API_KEY="YOUR_API_KEY"

# Required for agent example
# SERPAPI_API_KEY="YOUR_API_KEY"

# Required for the AI SDK agent example
# TAVILY_API_KEY="YOUR_API_KEY"

# Required for retrieval examples
# SUPABASE_PRIVATE_KEY="YOUR_SUPABASE_PRIVATE_KEY"
# SUPABASE_URL="YOUR_SUPABASE_URL"

# Optional: For Tracing with LangSmith
# LANGCHAIN_TRACING_V2=true
# LANGCHAIN_API_KEY=YOUR_API_KEY
# LANGCHAIN_PROJECT=nextjs-starter
EOF
printf '\n# cloudflare / opennext\n.open-next\n.wrangler\n.dev.vars\ncloudflare-env.d.ts\n' >> .gitignore
node -e '
const fs=require("fs");const p=JSON.parse(fs.readFileSync("package.json"));
p.scripts={...p.scripts,
 preview:"opennextjs-cloudflare build && opennextjs-cloudflare preview",
 deploy:"opennextjs-cloudflare build && opennextjs-cloudflare deploy",
 upload:"opennextjs-cloudflare build && opennextjs-cloudflare upload",
 "cf-typegen":"wrangler types --env-interface CloudflareEnv cloudflare-env.d.ts"};
fs.writeFileSync("package.json",JSON.stringify(p,null,2)+"\n");'
